def _immutable_triggers(table: str, label: str) -> tuple[str, str]:
    return (f"\nCREATE TRIGGER {CORE_PREFIX}{label}_immutable_update\nBEFORE UPDATE ON {table}\nBEGIN\n    SELECT RAISE(ABORT, '{label}_immutable');\nEND\n".strip(), f"\nCREATE TRIGGER {CORE_PREFIX}{label}_immutable_delete\nBEFORE DELETE ON {table}\nBEGIN\n    SELECT RAISE(ABORT, '{label}_immutable');\nEND\n".strip())

def _quest_completion_triggers(table: str, label: str) -> tuple[str, ...]:
    return (f"\nCREATE TRIGGER {CORE_PREFIX}{label}_insert_completed_guard\nBEFORE INSERT ON {table}\nWHEN NEW.status = 'completed'\nBEGIN\n    SELECT RAISE(ABORT, '{label}_completion_requires_transition');\nEND\n".strip(), f"\nCREATE TRIGGER {CORE_PREFIX}{label}_completed_update_guard\nBEFORE UPDATE ON {table}\nWHEN OLD.status = 'completed'\nBEGIN\n    SELECT RAISE(ABORT, '{label}_completed_guard:terminal_immutable');\nEND\n".strip(), f"\nCREATE TRIGGER {CORE_PREFIX}{label}_completed_delete_guard\nBEFORE DELETE ON {table}\nWHEN OLD.status = 'completed'\nBEGIN\n    SELECT RAISE(ABORT, '{label}_completed_guard:terminal_immutable');\nEND\n".strip(), f"\nCREATE TRIGGER {CORE_PREFIX}{label}_completion_evidence_gate\nBEFORE UPDATE OF status ON {table}\nWHEN NEW.status = 'completed' AND OLD.status <> 'completed'\nBEGIN\n    SELECT CASE WHEN NOT EXISTS (\n        SELECT 1 FROM {EVIDENCE_TABLE}\n        WHERE evidence_id = NEW.completion_evidence_id\n          AND project_id = NEW.project_id\n          AND verification_status = 'accepted'\n    ) THEN RAISE(ABORT, '{label}_completion_evidence_missing') END;\n    SELECT CASE WHEN NEW.human_approval_required = 1 AND NOT EXISTS (\n        SELECT 1 FROM {EVIDENCE_TABLE}\n        WHERE evidence_id = NEW.human_approval_evidence_id\n          AND project_id = NEW.project_id\n          AND evidence_kind = 'human_approval'\n          AND verification_status = 'accepted'\n    ) THEN RAISE(ABORT, '{label}_completion_human_approval_missing') END;\nEND\n".strip())

def _digest_format_triggers(table: str, label: str, columns: Sequence[str]) -> tuple[str, str]:
    checks = '\n'.join((f"    SELECT CASE WHEN NEW.{column} IS NOT NULL AND (length(NEW.{column}) <> 64 OR NEW.{column} GLOB '*[^0-9a-f]*') THEN RAISE(ABORT, '{label}_{column}_invalid') END;" for column in columns))
    return (f'\nCREATE TRIGGER {CORE_PREFIX}{label}_digest_insert_guard\nBEFORE INSERT ON {table}\nBEGIN\n{checks}\nEND\n'.strip(), f'\nCREATE TRIGGER {CORE_PREFIX}{label}_digest_update_guard\nBEFORE UPDATE ON {table}\nBEGIN\n{checks}\nEND\n'.strip())
